insert into public.advent_days(day,content,version) values (1,'{"day":1,"title":"Lettre interactive","intro":"Une enveloppe fictive attend sur la table de Loyal. Ouvre ses trois fragments, puis choisis ta réponse.","room":"house","reward":"Étoile 1 · Lettre interactive","steps":[{"id":"lettre","kind":"read","prompt":"Ouvrir les trois fragments de la lettre","items":[{"id":"1","label":"Debby, bienvenue dans cet hiver imaginaire."},{"id":"2","label":"Chaque petite attention peut devenir une étoile."},{"id":"3","label":"Ce voyage de démonstration nous attend, pas à pas."}]},{"id":"reponse","kind":"choice","prompt":"Que proposes-tu à Loyal ?","options":[{"id":"1","label":"Une promenade sous la neige"},{"id":"2","label":"Un thé au coin du feu"}]}],"version":1}'::jsonb,1) on conflict do nothing;
insert into private.advent_rules(day,rules) values (1,'{"lettre":{"minimum":3},"reponse":{}}'::jsonb) on conflict do nothing;
