insert into public.advent_days(day,content,version) values (15,'{"day":15,"title":"Histoire à choix","intro":"Choisis votre chemin dans une courte histoire fictive. Les deux routes mènent à un souvenir.","room":"library","reward":"Étoile 15 · Histoire à choix","steps":[{"id":"histoire","kind":"story","prompt":"Mener l’histoire jusqu’à sa fin","story":{"start":{"text":"Loyal tend la main à Debby. Où allons-nous ?","choices":[{"id":"foret","label":"Vers la forêt","next":"foret"},{"id":"place","label":"Vers les lanternes","next":"place"}]},"foret":{"text":"Un flocon se pose sur vos lunettes. La forêt semble écouter.","choices":[{"id":"retour","label":"Partager ce silence puis rentrer","next":"end"}]},"place":{"text":"Les lanternes éclairent vos pas. Un rire résonne sur la place.","choices":[{"id":"retour","label":"Garder ce rire en souvenir","next":"end"}]},"end":{"text":"Vous rentrez avec une histoire à raconter ensemble.","choices":[]}}}],"version":1}'::jsonb,1) on conflict do nothing;
